import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    # Be tolerant of input key casing/naming variations
    postings = None
    for key in ("POSTINGS", "postings", "Postings"):
        if key in inputs:
            postings = inputs[key].copy()
            break
    if postings is None:
        # fallback: try case-insensitive match
        for k, v in inputs.items():
            if k.lower() == "postings":
                postings = v.copy()
                break
    if postings is None:
        # last resort: empty frame with expected columns
        postings = pd.DataFrame(columns=["account_id", "post_seq", "post_date", "qty", "unit_price"])

    # Ensure expected columns exist even if input is empty
    cols = ["account_id", "post_seq", "post_date", "qty", "unit_price"]
    for c in cols:
        if c not in postings.columns:
            postings[c] = pd.Series(dtype="object")

    # Sort according to cursor ORDER BY account_id, post_date, post_seq
    # Use stable sort to preserve original relative order on ties
    postings_sorted = postings.sort_values(
        by=["account_id", "post_date", "post_seq"],
        kind="mergesort"
    ).reset_index(drop=True)

    posted_rows = []
    reject_rows = []

    prev_acct = None
    tot = 0.0
    rej = 0

    def is_null(v):
        if v is None:
            return True
        try:
            return bool(pd.isna(v))
        except Exception:
            return False

    for _, r in postings_sorted.iterrows():
        acct = r["account_id"]
        post_seq = r["post_seq"]
        post_date = r["post_date"]
        qty = r["qty"]
        unit_price = r["unit_price"]

        if acct != prev_acct:
            if prev_acct is not None:
                reject_rows.append({"account_id": prev_acct, "reject_count": rej})
            tot = 0.0
            rej = 0
            prev_acct = acct

        qty_null = is_null(qty)
        price_null = is_null(unit_price)

        reject = False
        qty_val = None
        price_val = None
        if qty_null or price_null:
            reject = True
        else:
            try:
                qty_val = float(qty)
                price_val = float(unit_price)
            except Exception:
                reject = True
                qty_val = None
                price_val = None

            if not reject:
                if qty_val <= 0 or price_val < 0:
                    reject = True

        if reject:
            rej += 1
        else:
            v = qty_val * price_val
            tot = tot + v
            posted_rows.append({
                "account_id": acct,
                "post_seq": post_seq,
                "post_date": post_date,
                "post_value": v,
                "running_total": tot,
            })

    if prev_acct is not None:
        reject_rows.append({"account_id": prev_acct, "reject_count": rej})

    posted_totals = pd.DataFrame(
        posted_rows,
        columns=["account_id", "post_seq", "post_date", "post_value", "running_total"]
    )
    reject_counts = pd.DataFrame(
        reject_rows,
        columns=["account_id", "reject_count"]
    )

    if not posted_totals.empty:
        posted_totals["account_id"] = posted_totals["account_id"].astype("int64")
        posted_totals["post_seq"] = posted_totals["post_seq"].astype("int64")
        posted_totals["post_value"] = posted_totals["post_value"].astype("float64")
        posted_totals["running_total"] = posted_totals["running_total"].astype("float64")
    else:
        posted_totals = posted_totals.astype({
            "account_id": "int64",
            "post_seq": "int64",
            "post_value": "float64",
            "running_total": "float64",
        })

    if not reject_counts.empty:
        reject_counts["account_id"] = reject_counts["account_id"].astype("int64")
        reject_counts["reject_count"] = reject_counts["reject_count"].astype("int64")
    else:
        reject_counts = reject_counts.astype({
            "account_id": "int64",
            "reject_count": "int64",
        })

    return {
        "posted_totals": posted_totals,
        "reject_counts": reject_counts,
    }
